package org.firstinspires.ftc.teamcode.config;

import com.pedropathing.math.Pose;

// Generated by refract-suite ftc-construct. Field frame: origin = red ALLIANCE wall x audience wall corner,
// +x toward blue, +y toward the far wall, heading 0 = +x, counter-clockwise positive.
public final class Field {
    public static final double SIZE = 144.0;
    public static final double CENTER = 72.0;
    // CELL opening is ~20 in wide (manual 9.6.2)
    public static final double CELL_HALF_WIDTH = 10.0;

    private Field() {}

    public static double[] rotate180(double x, double y) {
        return new double[]{SIZE - x, SIZE - y};
    }

    // Own CELL on the robot's side of y = 72 (the HIVE frame crossbar).
    public static double[] targetCell(MatchState.Alliance alliance, double robotY) {
        boolean farSide = robotY >= CENTER;
        if (alliance == MatchState.Alliance.RED) {
            return farSide
                    ? new double[]{Tuned.redFarCellX, Tuned.redFarCellY}
                    : new double[]{Tuned.redAudienceCellX, Tuned.redAudienceCellY};
        }
        // blue far CELL = rotated red audience CELL, blue audience CELL = rotated red far CELL
        return farSide
                ? rotate180(Tuned.redAudienceCellX, Tuned.redAudienceCellY)
                : rotate180(Tuned.redFarCellX, Tuned.redFarCellY);
    }

    public static boolean cornerReseedReady() {
        return Tuned.isSet(Tuned.centerToFront, Tuned.centerToBack, Tuned.centerToLeft, Tuned.centerToRight);
    }

    // Robot sitting square in the nearest corner: heading snapped to 90 deg, centre set back from both
    // walls by whichever robot edges face them.
    public static Pose cornerPose(Pose current) {
        double h = Math.round(current.heading() / (Math.PI / 2)) * (Math.PI / 2);
        double x = current.x() < CENTER ? edgeFacing(-1, 0, h) : SIZE - edgeFacing(1, 0, h);
        double y = current.y() < CENTER ? edgeFacing(0, -1, h) : SIZE - edgeFacing(0, 1, h);
        return new Pose(x, y, h);
    }

    // Distance from robot centre to the robot edge that faces field direction (dx, dy).
    static double edgeFacing(double dx, double dy, double heading) {
        double forward = Math.cos(heading) * dx + Math.sin(heading) * dy;
        double left = -Math.sin(heading) * dx + Math.cos(heading) * dy;
        if (Math.abs(forward) > Math.abs(left)) {
            return forward > 0 ? Tuned.centerToFront : Tuned.centerToBack;
        }
        return left > 0 ? Tuned.centerToLeft : Tuned.centerToRight;
    }

    // Tuning / practice start position (not the auto start): stand behind your alliance wall facing the field;
    // the robot sits in the corner on your RIGHT (your GARDEN corner, cleared of POLLEN), back flat against
    // your alliance wall, right side flat against the side wall, front facing straight across the field.
    // Red: (back edge, right edge) from the (0, 0) corner, heading 0. Blue: the 180-degree turn of that.
    public static Pose startPose(MatchState.Alliance alliance) {
        if (alliance == MatchState.Alliance.BLUE) {
            return new Pose(SIZE - Tuned.centerToBack, SIZE - Tuned.centerToRight, Math.PI);
        }
        return new Pose(Tuned.centerToBack, Tuned.centerToRight, 0);
    }

    public static double wrapDeg(double deg) {
        double d = deg % 360.0;
        if (d > 180.0) d -= 360.0;
        if (d <= -180.0) d += 360.0;
        return d;
    }
}
